const payload = ($input.first().json.body ?? $input.first().json);

const typeLabel = {
  background_check: 'background-check form',
  reference_check: 'reference-check form',
  employment_verification: 'employment-verification form',
  onboarding_form: 'onboarding form',
}[payload.reminderType] || 'requested form';

const to = String(payload.recipientEmail || '').trim();
const name = String(payload.recipientName || 'there').trim();
const person = String(payload.subjectName || '').trim();
if (!to) throw new Error('recipientEmail is required');

const subject = `Reminder: ${typeLabel} | Romega Solutions`;
const body = `Hi ${name},

This is a friendly reminder to complete the ${typeLabel}${person ? ` for ${person}` : ''}. Please use the original email/link we sent you.

If you cannot find the original email or need help, please reply to this message.

Thank you,
Romega Solutions`;

return [{ json: { to, subject, body, template: 'manual-form-reminder', source: payload.source, reminderType: payload.reminderType } }];

const email = String($json.to || '').trim().toLowerCase();
const payload = ($('Webhook').first().json.body ?? $('Webhook').first().json);
const cc = [...new Set(
  [payload.requestedByEmail, payload.onboardingLeadEmail]
    .map((value) => String(value || '').trim().toLowerCase())
    .filter((value) => value && value !== email),
)].join(',');

return [{ json: { ...$json, cc } }];

const payload = ($('Webhook').first().json.body ?? $('Webhook').first().json);
const escapeHtml = (value) => String(value ?? '').replace(/[&<>"']/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);
const typeLabel = {
  background_check: 'background-check form',
  reference_check: 'reference-check form',
  employment_verification: 'employment-verification form',
  onboarding_form: 'onboarding form',
}[payload.reminderType] || 'requested form';
const name = escapeHtml(payload.recipientName || 'there');
const subjectName = escapeHtml(payload.subjectName || '');
const subjectSuffix = subjectName ? ' for ' + subjectName : '';

const htmlBody = [
  '<!doctype html>',
  '<html lang=' + "'en'" + '>',
  '<body style=' + "'margin:0;padding:0;background:#f4f7fb;font-family:Arial,Helvetica,sans-serif;color:#1f2937;'" + '>',
  '<table role=' + "'presentation'" + ' width=' + "'100%'" + ' cellspacing=' + "'0'" + ' cellpadding=' + "'0'" + ' style=' + "'padding:32px 16px;'" + '><tr><td align=' + "'center'" + '>',
  '<table role=' + "'presentation'" + ' width=' + "'100%'" + ' cellspacing=' + "'0'" + ' cellpadding=' + "'0'" + ' style=' + "'max-width:600px;background:#ffffff;border:1px solid #d9e2f0;border-radius:16px;overflow:hidden;'" + '>',
  '<tr><td style=' + "'padding:28px 36px 24px;background:#0f4c81;color:#ffffff;'" + '><p style=' + "'margin:0 0 8px;font-size:11px;font-weight:700;letter-spacing:1.8px;'" + '>ROMEGA SOLUTIONS</p><h1 style=' + "'margin:0;font-size:27px;line-height:1.25;font-family:Georgia,serif;'" + '>A quick reminder</h1></td></tr>',
  '<tr><td style=' + "'padding:34px 36px 20px;font-size:16px;line-height:1.65;'" + '>',
  '<p style=' + "'margin:0 0 20px;'" + '>Hi ' + name + ',</p>',
  '<p style=' + "'margin:0 0 24px;'" + '>Just a friendly reminder to complete the <strong>' + escapeHtml(typeLabel) + '</strong>' + subjectSuffix + '.</p>',
  '<div style=' + "'margin:0 0 24px;padding:18px 20px;border-left:4px solid #1d8acb;background:#edf7ff;border-radius:4px;'" + '><p style=' + "'margin:0;font-size:14px;line-height:1.55;color:#174a6b;'" + '><strong>Please use the original email and link we sent you.</strong><br>That link remains the secure way to submit your form.</p></div>',
  '<p style=' + "'margin:0 0 26px;'" + '>Cannot find the original email or need help? Reply to this message and we will assist you.</p>',
  '<p style=' + "'margin:0;'" + '>Thank you,<br><strong>Romega Solutions</strong></p>',
  '</td></tr>',
  '<tr><td style=' + "'padding:18px 36px;background:#f8fafc;border-top:1px solid #e5eaf1;color:#64748b;font-size:12px;line-height:1.5;'" + '>This is a reminder about your pending Romega Solutions form.</td></tr>',
  '</table></td></tr></table>',
  '</body></html>',
].join('');

return [{ json: { ...$json, htmlBody } }];
